changeSet.sql:
create or alter procedure [api].[MergeAssetPaths] @executionId uniqueidentifier = null, @class int, @begin int, @end int, @assetTypeUid uniqueidentifier = null, @onlyInsert bit = 0 as begin set nocount on;
drop table if exists #hierarchy drop table if exists #tbl drop table if exists #incoming
create table #hierarchy ( GroupID bigint, AssetTypeID int, ID bigint, [Level] int, ParentID bigint, Code nvarchar(250) )
create table #tbl ( GroupID bigint, AssetTypeID int,
ID bigint, [Level] int, [Position] decimal(5,3),
ParentID bigint, ParentLevel int, ParentPosition decimal(5,3),
ColumnOrder int, FormattedValue nvarchar(max) )
create table #incoming (ID bigint)
insert into #incoming select AssetID from api.ExecutionAsset where ExecutionID = @executionId and ItemNumber between @begin and @end
if @class = 15 begin insert into #incoming select A.ID as AssetID from api.ExecutionDiagramAsset EDA inner join Asset A ON A.uid = EDA.Uid where ExecutionID = @executionId end
if @class = 11 begin insert into #incoming select AssetID from api.ExecutionUser where ExecutionID = @executionId and ItemNumber between @begin and @end end
if @assetTypeUid is not null begin insert into #incoming select A.ID from AssetType AT inner join Asset A on A.AssetTypeID = AT.ID where AT.uid = @assetTypeUid end
drop table if exists #TempIntersectTypeIDs; create table #TempIntersectTypeIDs(IntersectTypeID int); create clustered index cx_TempIntersectTypeIDs on #TempIntersectTypeIDs (IntersectTypeID);
insert into #TempIntersectTypeIDs select IT.ID IntersectTypeID From [IntersectType] IT inner join [Predicate] P on IT.PredicateID = P.ID and P.Type in (3,4);
if exists (select top 1 * from #incoming) begin with descendants as ( select I.SubjectAssetID, I.ObjectAssetID from #incoming O inner join [Intersect] I on I.SubjectAssetID = O.ID and I.IntersectTypeID in (select IntersectTypeID from #TempIntersectTypeIDs) union all select I.SubjectAssetID, I.ObjectAssetID from descendants c inner join [Intersect] I on I.SubjectAssetID = c.ObjectAssetID and I.IntersectTypeID in (select IntersectTypeID from #TempIntersectTypeIDs) ) insert into #incoming select distinct ObjectAssetID from descendants;
create clustered index CIX_TempIncoming on #incoming (ID)
if @class = 15 --diagram asset, we need to go through a different relationship. begin with hierarchy as ( select DA.ID as GroupID, DA.AssetTypeID, DA.ID as AssetId, A.ID as ParentAssetId, DA.Code, 0 as [Level] from Asset A inner join AssetProcessDiagram D on D.AssetID = A.ID cross apply openjson(D.Diagram, '$.nodeDataArray') with (assetUid uniqueidentifier N'$.key') N inner join Asset DA on DA.Uid = N.assetUid inner join #incoming O on O.ID = DA.ID union all select c.GroupID, A.AssetTypeID, A.ID as AssetId, I.SubjectAssetID as ParentAssetId, A.Code, c.[Level]-1 as [Level] from hierarchy c inner join Asset A on A.ID = c.ParentAssetId inner join [Intersect] I on I.ObjectAssetID = a.ID inner join [IntersectType] IT on IT.ID = I.IntersectTypeID inner join [Predicate] P on P.ID = IT.PredicateID where P.Type in (3,4)
)
insert into #hierarchy (GroupID, AssetTypeID, ID, [Level], ParentID, Code) select A.GroupID, A.AssetTypeID, A.AssetId, A.[Level], P.ID, A.Code from hierarchy A left join Asset P on P.ID = A.ParentAssetId; end else begin with hierarchy as ( select O.ID as GroupID, O.ID, I.ObjectAssetID, I.SubjectAssetID as ParentObjectAssetID, 0 as [Level] from #incoming O left join [Intersect] I on I.ObjectAssetID = O.ID and I.IntersectTypeID in (select IntersectTypeID from #TempIntersectTypeIDs) union all select c.GroupID, c.ParentObjectAssetID ID, c.ParentObjectAssetID ObjectAssetID, I.SubjectAssetID as ParentObjectAssetID, c.[Level]-1 as [Level] from hierarchy c outer apply ( select I.SubjectAssetID from [Intersect] I where I.ObjectAssetID = c.ParentObjectAssetID and I.IntersectTypeID in (select IntersectTypeID from #TempIntersectTypeIDs) ) I where c.ParentObjectAssetID is not null )
insert into #hierarchy (GroupID, AssetTypeID, ID, [Level], ParentID, Code) select A.GroupID, ad.AssetTypeID, A.ID, A.[Level], P.ID, ad.Code from hierarchy A inner join asset ad on ad.id = a.id left join Asset P on P.ID = A.ParentObjectAssetID; end
if @class = 9 begin insert into #tbl (GroupID, AssetTypeID, ID, [Level], [Position], ParentID, ParentLevel, ColumnOrder, FormattedValue) select GroupID, AssetTypeID, ID, [Level], cast(cast([Level] as varchar) + '.1' as decimal(5,3)) as Position, ParentID, [Level] - 1, 1, Code from #hierarchy end else if @class = 11 begin create nonclustered index CIX_TempHierarchy on #hierarchy (ID)
insert into #tbl (GroupID, AssetTypeID, ID, [Level], [Position], ParentID, ParentLevel, ColumnOrder, FormattedValue) select GroupID, H.AssetTypeID, H.ID, [Level], cast(cast([Level] as varchar) + '.1' as decimal(5,3)) as Position, H.ParentID, [Level] - 1, 1, F.FirstName + ' ' + F.LastName from #hierarchy H inner join Asset A on A.ID = H.ID inner join assettype att on att.id = a.AssetTypeID and att.Class = 11 inner join reporting.Global_Resource F on F.ResourceID = A.SourceID end else if @class = 12 begin create nonclustered index CIX_TempHierarchy on #hierarchy (ID)
insert into #tbl (GroupID, AssetTypeID, ID, [Level], [Position], ParentID, ParentLevel, ColumnOrder, FormattedValue) select GroupID, H.AssetTypeID, H.ID, [Level], cast(cast([Level] as varchar) + '.1' as decimal(5,3)) as Position, H.ParentID, [Level] - 1, 1, F.Name from #hierarchy H inner join Asset A on A.ID = H.ID inner join assettype att on att.id = a.AssetTypeID and att.Class = 12 inner join dbo.[Group] F on F.ID = A.SourceID end else begin drop table if exists #tempfldtype; With RS as (Select distinct AssetTypeID From #hierarchy ) select FT.ID, FT.ColumnOrder, FT.DefaultFormattedValue, FT.AssetTypeID, FT.Type, FT.CounterPrefix into #tempfldtype from RS A inner join FieldType FT on FT.AssetTypeID = A.AssetTypeID and FT.IsPartOfKey = 1;
create clustered index cx_tempfldtype on #tempfldtype(AssetTypeID,ID);
create nonclustered index CIX_TempHierarchy on #hierarchy (AssetTypeID)
insert into #tbl (GroupID, AssetTypeID, ID, [Level], [Position], ParentID, ParentLevel, ColumnOrder, FormattedValue) select distinct A.GroupID, A.AssetTypeID, A.ID, A.[Level], cast(cast(A.[Level] as varchar) + '.' + cast(FT.ColumnOrder as varchar) as decimal(5,3)) as Position, A.ParentID, A.[Level] - 1, FT.ColumnOrder, coalesce(F.FormattedValue, FT.DefaultFormattedValue) as FormattedValue from #hierarchy A inner join #tempfldtype FT on FT.AssetTypeID = A.AssetTypeID left join Field F on F.FieldTypeID = FT.ID and F.AssetID = A.ID where coalesce(F.FormattedValue, FT.DefaultFormattedValue) is not null --handle counter fields if exists(select 1 from #tempfldtype FT where FT.Type = 'Counter') Begin insert into #tbl (GroupID, AssetTypeID, ID, [Level], [Position], ParentID, ParentLevel, ColumnOrder, FormattedValue) select distinct A.GroupID, A.AssetTypeID, A.ID, A.[Level], cast(cast(A.[Level] as varchar) + '.' + cast(FT.ColumnOrder as varchar) as decimal(5,3)) as Position, A.ParentID, A.[Level] - 1, FT.ColumnOrder, coalesce(FT.CounterPrefix,'')+ cast(FCV.Value as nvarchar(20)) as FormattedValue from #hierarchy A inner join #tempfldtype FT on FT.AssetTypeID = A.AssetTypeID and FT.Type = 'Counter' inner join FieldCounterValue FCV on FCV.AssetId = A.Id and FCV.FieldTypeId = FT.Id end end drop table if exists #hierarchy; drop table if exists #incoming; drop table if exists #TempIntersectTypeIDs; drop table if exists #tempfldtype;
create clustered index CIX_TempTbl on #tbl (GroupID);
exec api.ParseAssetPaths; drop table if exists #tbl; end end
